    data = pathlib.Path(p).read_text()
    out = set()
    for m in re.finditer(r"-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----", data, re.S):
        cert = m.group(0) + "\n"
        out.add(subprocess.run(["openssl","x509","-noout","-subject"], input=cert.encode(), capture_output=True).stdout.decode().strip())
